def _parse(blob, exchange):
    out = []
    for row in blob.split(";"):
        s, n, sec = row.split("|")
        out.append({"symbol": s, "name": n, "sector": sec, "exchange": exchange})
    return out


STOCKS = _parse(_US, "US") + _parse(_IN, "NSE")
